// Canonical form
{ "type": "plot", "marks": ["line"],         "series": [...] }
{ "type": "plot", "marks": ["line","area"], "series": [...] }
{ "type": "plot", "marks": ["dots"],         "series": [...] }

// Sugar — still works
{ "type": "line", "series": [...] }   // → plot, marks: ["line"]
{ "type": "area", "series": [...] }   // → plot, marks: ["line", "area"]
